function avatar(p,classes=''){return `<div class="avatar ${esc(p.color||'')} ${classes}">${p.photo?`<img src="${p.photo}" alt="${esc(p.name)} 프로필 사진">`:p.id==='admin'?icon('chat'):esc(p.short||p.name.slice(-2))}</div>`}
function verify(){return `<span class="verified" aria-label="공식 참여팀">${icon('verified')}</span>`}
function iconButton(name,action,label,extra=''){const extraClass=extra.match(/class="([^"]*)"/);return `<button type="button" class="icon-btn ${extraClass?extraClass[1]:''}" data-action="${action}" aria-label="${label}" ${extra.replace(/class="[^"]*"/,'')}>${icon(name)}</button>`}
function currentIdentity(){return currentWorkspaceIdentity();}

function roomList(){return accessRooms();}

function activeRoom(){return roomList().find(r=>r.id===state.room)||roomList()[0]}
function navItems(){return accessNavItems();}

function renderShell(){renderAccessShell();}

function render(){
 if(!access.signedIn){renderLogin();return;}
 reconcilePermissions();renderShell();
 const views={chats:renderChat,inbox:renderChat,friends:renderFriends,news:renderNews,profile:renderProfile,submissions:renderSubmissions,team:renderTeamPage,'team-manage':renderTeamManagement,'ops-teams':renderOperationsTeams,'ops-access':renderOperationsAccess};
 (views[state.view]||renderChat)();applyVisiblePermissions();
}

function statusClass(s){return s==='검토 중'?'review':s==='완료'?'done':s==='보완 요청'?'pending':'private'}
function statusPill(s){return `<span class="status-pill ${statusClass(s)}">${esc(s)}</span>`}
function roomRow(r){const isAdmin=state.role==='admin';return `<button class="room-row ${r.id===state.room?'active':''}" data-action="room" data-id="${r.id}" data-search="${esc(r.title+' '+r.preview)}">${avatar(r.peer)}<div class="room-copy"><div class="room-top"><span class="room-name">${esc(r.title)}${r.kind==='team'||r.kind==='ops'?verify():''}</span>${!isAdmin?`<span class="room-time">${r.time}</span>`:''}</div><div class="room-bottom"><p class="room-preview">${esc(r.preview)}</p>${r.unread&&!isAdmin?`<span class="badge">${r.unread}</span>`:''}</div>${isAdmin?`<div class="admin-room-meta">${statusPill(r.submission.status)}<span>${r.time}</span></div>`:''}</div></button>`}
function renderChat(){
 const isAdmin=state.role==='admin';let list=roomList();
 if(isAdmin&&state.adminFilter!=='all')list=list.filter(r=>r.submission.status===state.adminFilter);
 else if(!isAdmin&&state.chatFilter!=='all')list=list.filter(r=>state.chatFilter==='group'?r.kind==='group':state.chatFilter==='internal'?r.kind==='internal':state.chatFilter==='person'?r.kind==='person':r.kind==='team'||r.kind==='ops');
 const room=activeRoom();state.room=room.id;if(isAdmin&&room.submission)state.activeSubmission=room.submission.id;
 const ops=room.kind==='ops',sub=room.submission||submissions.find(s=>s.room===room.id),isGroup=room.kind==='group'||room.kind==='internal';
 document.querySelector('#main').innerHTML=`<div class="messenger ${state.mobileOpen?'room-open':''}"><section class="conversation-list ${isAdmin?'admin-list':''}" aria-label="대화 목록"><div class="list-header"><h1 class="visually-hidden">${isAdmin?'업무함':'대화'}</h1><div class="list-search-row"><div class="search-box">${icon('search')}<input id="chat-search" type="search" placeholder="${isAdmin?'팀 이름, 접수 내용 검색':'이름, 대화방 검색'}" aria-label="대화 검색"></div>${isAdmin?'':`<div class="desktop-screen-actions">${screenActionMarkup()}</div>`}</div>${isAdmin?`<div class="admin-stats"><div class="admin-stat"><strong>${allowedSubmissions().filter(s=>s.status==='접수됨').length}</strong><span>새 접수</span></div><div class="admin-stat"><strong>${allowedSubmissions().filter(s=>s.status==='검토 중').length}</strong><span>검토 중</span></div><div class="admin-stat"><strong>${allowedSubmissions().filter(s=>s.status==='보완 요청').length}</strong><span>보완 대기</span></div></div>`:`<div class="chips">${(state.role==='team'?[['all','전체'],['internal','내부 대화'],['person','후원자'],['team','운영방']]:[['all','전체'],['team','참여팀'],['group','단체 대화']]).map(([id,l])=>`<button class="chip ${state.chatFilter===id?'active':''}" data-chatfilter="${id}">${l}</button>`).join('')}</div>`}</div>${state.role==='team'?`<div class="list-section-label">${icon('pin')}공식 운영 대화</div>`:''}<div id="room-results">${list.map(roomRow).join('')||'<div class="empty">대화방이 없습니다.</div>'}</div></section><section class="chat-panel" aria-label="${esc(room.title)} 대화방"><header class="chat-header"><div class="chat-identity">${iconButton('back','back-list','대화 목록으로','class="mobile-back"').replace('class="icon-btn"','class="icon-btn mobile-back"')}${avatar(room.peer)}<div><h2>${esc(room.title)}${ops||room.kind==='team'?verify():''}</h2><p>${ops?(isAdmin?'운영 자료 · 담당 김하늘':'모두의기부 공식 운영 채널'):isGroup?`${room.count||1}명 참여${room.pending?' · '+room.pending+'명 초대 대기':''}`:room.kind==='team'?'내가 후원한 팀':'서로 친구로 연결되어 있어요'}</p></div></div><div class="actions">${iconButton('search','room-search','대화 내용 검색','class="optional"')}${iconButton('more','room-info','대화방 정보')}</div></header>${ops?`<div class="chat-notice">${icon('lock')}운영 대화의 자료는 공개되지 않습니다.${sub?`<button data-action="submission" data-id="${sub.id}">접수 건 보기</button>`:''}</div>`:isGroup?`<div class="chat-notice">${icon('pin')}${room.pending?'초대 수락을 기다리고 있어요.':'토요일 오전 10시, 함께 만나요.'}<button data-action="group-info">방 정보</button></div>`:''}<div class="chat-body" id="chat-body"><div class="chat-date"><span>2026년 9월 27일 일요일</span></div>${(messages[room.id]||[{system:'첫 메시지로 인사를 나눠보세요.'}]).map(m=>messageHTML(m,room)).join('')}</div><div class="composer-wrap"><form id="chat-form" class="composer">${iconButton('plus','attach','사진 또는 파일 첨부')}<textarea id="message-input" rows="1" placeholder="${ops?'메시지와 함께 자료를 보내세요':'메시지를 입력하세요'}" aria-label="메시지 입력"></textarea><button type="submit" class="send-btn" aria-label="메시지 전송">${icon('send')}</button></form><p class="composer-note">Enter로 전송 · Shift + Enter로 줄바꿈</p></div></section>${chatInfo(room,sub)}</div>`;
 requestAnimationFrame(()=>{const body=document.querySelector('#chat-body');if(body)body.scrollTop=body.scrollHeight;});
}
function messageHTML(m,room){
 if(m.system)return `<div class="system-msg">${esc(m.system)}</div>`;
 const mine=m.from===state.role;let author=m.from==='admin'?{id:'admin',name:'모두의기부',short:'모두',color:'official'}:m.from==='team'?(room.peer.id&&teams.some(t=>t.id===room.peer.id)?room.peer:team(m.teamId||state.workspaceTeamId||'haebom')):m.from==='supporter'?me:room.peer;
 if(m.senderName)author={name:m.senderName,short:m.senderName.slice(-2),color:'blue'};let body='';
 if(m.post){let p=posts.find(p=>p.id===m.post);body=p?`<button class="message-photo" data-action="post" data-id="${p.id}"><img src="${p.image}" alt="${esc(p.title)}"><span class="photo-caption">${esc(p.title)}${icon('chevron')}</span></button>`:'<div class="bubble">이 소식은 더 이상 표시되지 않습니다.</div>';}
 else if(m.file)body=fileCard(m.file);
 else if(m.receipt){const s=submissions.find(s=>s.id===m.receipt);body=`<div class="receipt-card">${statusPill(s.status)}<h3>${esc(s.title)}</h3><p>최신 파일 ${s.files.length?esc(sampleFiles[s.files[0]]?.type||'문서'):''} · 담당 ${esc(s.assignee)}</p><button class="btn wide" data-action="submission" data-id="${s.id}">접수 내용 보기 ${icon('chevron')}</button></div>`;}
 else body=`<div class="bubble">${esc(m.text)}</div>`;
 return `<div class="message ${mine?'mine':''}">${mine?'':avatar(author)}<div class="message-content">${mine?'':`<div class="message-author">${esc(author.name)}</div>`}<div class="message-body">${body}<div class="msg-meta">${mine?'<span class="read-count"></span>':''}${esc(m.time||'방금')}</div></div></div></div>`;
}
function fileCard(id){const f=sampleFiles[id]||state.localFiles.get(id);if(!f)return '';if(f.image)return `<button class="message-photo" data-action="file" data-id="${id}"><img src="${f.url}" alt="${esc(f.name)}"><span class="photo-caption">${esc(f.name)}${icon('chevron')}</span></button>`;return `<button class="file-card" data-action="file" data-id="${id}"><span class="file-icon ${f.type==='PDF'?'':'word'}">${esc(f.type)}</span><span class="file-copy"><strong>${esc(f.name)}</strong><span>${esc(f.size)} · ${f.url?'첨부파일':'문서 미리보기'}</span></span>${icon('chevron')}</button>`}
function chatInfo(room,sub){const p=room.peer;return `<aside class="chat-info" aria-label="대화방 상세"><div class="info-profile">${avatar(p,'big')}<h3>${esc(p.name)}</h3><p>${room.kind==='ops'?(state.role==='admin'?team(p.id).category+' · 참여팀':'운영 자료와 요청을 보내주세요'):room.kind==='team'?p.category+' · 후원으로 연결된 친구':'함께 나누는 일상의 이야기'}</p><button class="btn wide" data-action="${room.kind==='ops'?'submission':'team-page'}" data-id="${room.kind==='ops'?sub?.id||'sub1':p.id||'haebom'}">${room.kind==='ops'?'접수 내용 보기':'팀 페이지'}${icon('chevron')}</button></div>${sub?`<div class="info-block"><h3>현재 접수 건</h3><p>${esc(sub.title)}</p><div class="detail-row" style="margin-top:15px"><span>처리 상태</span>${statusPill(sub.status)}</div><div class="detail-row"><span>담당자</span><span>${esc(sub.assignee)}</span></div><div class="detail-row"><span>최근 접수</span><span>오늘 ${sub.time}</span></div></div><div class="info-block"><h3>제출 자료 <span class="count">${sub.files.length}</span></h3>${sub.files.map(id=>{const f=sampleFiles[id]||state.localFiles.get(id);return `<button class="info-file" data-action="file" data-id="${id}"><span class="file-icon ${f.type==='PDF'?'':'word'}">${f.type}</span><span class="file-copy"><strong>${esc(f.name)}</strong><span>${f.size}${id==='plan'?' · 최신본':' · 이전 기록'}</span></span></button>`}).join('')}</div>${state.role==='admin'?`<div class="admin-actions"><button class="btn light" data-action="review" data-status="완료" data-id="${sub.id}">완료 처리</button><button class="btn" data-action="review" data-status="보완 요청" data-id="${sub.id}">보완 요청</button><button class="btn" data-action="internal-note" data-id="${sub.id}">내부 메모</button></div>`:''}`:`<div class="info-block"><h3>함께 나눈 사진</h3><div class="info-photos">${posts.filter(p=>!p.mine).slice(0,3).map(p=>`<button data-action="post" data-id="${p.id}" aria-label="${esc(p.title)}"><img src="${p.image}" alt="${esc(p.title)}"></button>`).join('')}</div></div><div class="info-block"><h3>파일</h3><button class="info-file" data-action="file" data-id="report"><span class="file-icon">PDF</span><span class="file-copy"><strong>9월_활동소식.pdf</strong><span>2.4 MB · 9월 25일</span></span></button></div><div class="info-separator"><button class="btn wide" data-action="toggle-mute">${icon('bell')}알림 ${state.muted.has(room.id)?'켜기':'끄기'}</button></div>`}</aside>`}
function renderFriends(){
 const isTeam=state.role==='team';
 const search=`<div class="search-box friend-toolbar">${icon('search')}<input id="friend-search" placeholder="${isTeam?'후원 친구 이름 검색':'친구, 참여팀 검색'}" value="${esc(state.friendQuery)}" aria-label="친구 검색"></div>`;
 document.querySelector('#main').innerHTML=`<div class="page friends-page root-page ${isTeam?'friends-team':'friends-personal'}"><h1 class="visually-hidden">${isTeam?'후원 친구':'친구'}</h1><div class="friends-layout"><section><div class="friends-search-row">${search}<div class="desktop-screen-actions">${screenActionMarkup()}</div></div>${isTeam?`<div class="friends-summary"><span>후원 친구 <strong>${team(state.workspaceTeamId).supporters}</strong>명</span><span>후원으로 자동 연결</span></div>`:`<div class="section-line"><h2>내가 후원한 팀 <span class="count">${teams.length}</span></h2><span>후원으로 자동 연결</span></div><div id="team-friends">${teams.map(t=>friendRow(t,true)).join('')}</div><div class="section-line"><h2>개인 친구 <span class="count">${people.length}</span></h2></div>`}<div id="friend-results">${friendResults()}</div>${isTeam?`<button class="btn wide" id="load-more" data-action="more-friends" style="margin-top:16px">친구 더 보기 ${icon('down')}</button>`:''}</section>${isTeam?'':`<aside><div class="request-card"><h2>받은 친구 요청 <span class="count">${requests.length}</span></h2>${requests.map(p=>`<div class="request-person">${avatar(p,'sm')}<div><strong>${esc(p.name)}</strong><p>${esc(p.bio)}</p></div></div><div class="request-buttons"><button class="btn" data-action="reject-friend" data-id="${p.id}">나중에</button><button class="btn light" data-action="accept-friend" data-id="${p.id}">수락</button></div>`).join('')||'<p class="small muted">받은 요청이 없습니다.</p>'}</div></aside>`}</div></div>`;
}
function friendRow(p,isTeam=false){return `<div class="team-friend" data-search="${esc(p.name)}"><button data-action="${isTeam?'team-page':'person'}" data-id="${p.id}" style="padding:0">${avatar(p,isTeam?'':'round')}</button><div class="friend-copy"><strong>${esc(p.name)}${isTeam?verify():''}</strong><p>${esc(isTeam?p.category+' · 후원 중':p.bio)}</p></div><div class="friend-links"><button class="icon-btn" data-action="friend-chat" data-id="${p.id}" aria-label="${esc(p.name)}님과 대화">${icon('chat')}</button></div></div>`}
function friendResults(){let list=state.role==='team'?teamDonors():people;list=list.filter(p=>(p.name+' '+p.bio).includes(state.friendQuery));return list.slice(0,state.friendLimit).map(p=>friendRow(p)).join('')||'<div class="empty">검색 결과가 없습니다.</div>'}
function visibleProfilePosts(){return posts.filter(p=>(p.mine||p.team&&state.auto[p.team]&&state.showTeam[p.team]&&p.audience==='전체 공개')&&!state.hiddenPosts.has(p.id)).filter(p=>state.profileFilter==='all'||(state.profileFilter==='mine'?p.mine:!p.mine));}
function photoGrid(items){return `<div class="photo-grid">${items.map(p=>`<button class="photo-tile" data-action="post" data-id="${p.id}" aria-label="${esc(p.title)}"><img src="${p.image}" alt="${esc(p.title)}" loading="lazy" ${p.mine?'style="object-position:left;transform:scale(1.15)"':''}><span class="photo-source">${icon(p.mine?'profile':'heart')}${esc(p.mine?'나의 활동':p.person?person(p.person).name+'의 활동':team(p.team).name)}</span>${p.mine?'<span class="type-tag">직접 올린 활동</span>':''}</button>`).join('')}</div>`}
function renderProfile(){if(state.role==='team'){state.activeTeam=state.workspaceTeamId;renderTeamPage(true);return;}const friend=state.profilePerson?person(state.profilePerson):null,p=friend||me;const profileTeams=friend?teams.filter(t=>t.id!=='daon'):teams.filter(t=>state.showTeam[t.id]);const data=friend?posts.filter(p=>(p.team&&p.team!=='daon'&&p.audience==='전체 공개'||p.person===friend.id)&& (state.profileFilter==='all'||(state.profileFilter==='mine'?p.person===friend.id:!!p.team))):visibleProfilePosts();document.querySelector('#main').innerHTML=`<div class="page profile-page ${friend?'detail-page':'root-page own-profile'}">${friend?`<header class="detail-topline">${iconButton('back','own-profile','내 프로필로')}<h1>친구 프로필</h1></header>`:'<h1 class="visually-hidden">내 프로필</h1>'}<section class="profile-summary">${friend?'':`<div class="desktop-screen-actions profile-desktop-action">${screenActionMarkup()}</div>`}${avatar(p,'large')}<div class="profile-summary-content"><h2 class="profile-name">${esc(p.name)}</h2><p class="profile-bio">${esc(p.bio)}</p><div class="profile-stats"><span><strong>${profileTeams.length}</strong>함께하는 팀</span><span><strong>${friend?12:people.length}</strong>친구</span></div></div><div class="profile-actions">${friend?`<button class="btn light" data-action="friend-chat" data-id="${p.id}">${icon('chat')}대화</button>`:`<button class="btn" data-action="edit-profile">프로필 편집</button><button class="btn light" data-action="compose-post">${icon('plus')}활동 올리기</button>`}</div></section><section class="profile-teams"><div class="profile-teams-heading"><h2>${friend?'응원하는 곳':'내가 응원하는 곳'}</h2></div><div class="team-thumbnail-list">${profileTeams.map(t=>`<button class="team-thumbnail" data-action="team-page" data-id="${t.id}"><div class="team-thumb-img"><img src="${posts.find(p=>p.team===t.id&&p.audience==='전체 공개')?.image||t.image}" alt="${esc(t.name)}의 최신 활동"></div><span>${esc(t.name)}</span></button>`).join('')}</div></section><div class="profile-filter"><div class="tab-line">${[['all','전체'],['support','후원 소식'],['mine','나의 활동']].map(([id,l])=>`<button class="${state.profileFilter===id?'active':''}" data-profilefilter="${id}">${l}</button>`).join('')}</div><span>${icon('lock')}${esc(friend?'친구 공개':state.privacy)}</span></div>${data.length?photoGrid(data):'<div class="empty">이곳에 새로운 활동이 쌓입니다.</div>'}</div>`}
function postCard(p){const author=p.mine?me:p.person?person(p.person):team(p.team);return `<article class="post-card"><div class="post-head">${avatar(author,'sm')}<div class="post-author"><strong>${esc(author.name)}${p.team?verify():''}</strong><small>${esc(p.date)} · ${p.mine?'나의 활동':p.person?'친구의 활동':'후원하는 팀의 소식'}</small></div>${iconButton('more','post-menu','소식 메뉴',`data-id="${p.id}"`)}</div><button class="post-image-btn" data-action="post" data-id="${p.id}"><img src="${p.image}" alt="${esc(p.title)}" loading="lazy"></button><div class="post-actions"><div class="actions"><button class="icon-btn ${p.liked?'liked':''}" data-action="like" data-id="${p.id}" aria-label="응원하기" aria-pressed="${p.liked}">${icon('heart')}</button><button class="icon-btn" data-action="post" data-id="${p.id}" aria-label="댓글 보기">${icon('chat')}</button><button class="icon-btn" data-action="share-post" data-id="${p.id}" aria-label="대화로 소식 보내기">${icon('send')}</button></div><span>${p.likes}명이 응원했어요</span></div><div class="post-copy"><strong>${esc(p.title)}</strong><p>${esc(p.text)}</p>${p.team?`<button class="source-link" data-action="team-page" data-id="${p.team}">${esc(author.name)} 페이지 ${icon('chevron')}</button>`:''}</div></article>`}
function renderNews(){
 const isTeam=state.role==='team';
 const data=isTeam?posts.filter(p=>p.team===state.workspaceTeamId):posts.filter(p=>state.newsFilter==='friends'?!!p.person:state.newsFilter==='teams'?!!p.team:true);
 const filters=!isTeam?`<div class="chips">${[['all','전체'],['teams','후원한 팀'],['friends','친구 활동']].map(([id,l])=>`<button class="chip ${state.newsFilter===id?'active':''}" data-newsfilter="${id}">${l}</button>`).join('')}</div>`:'';
 document.querySelector('#main').innerHTML=`<div class="page news-page root-page ${isTeam?'team-news':''}"><h1 class="visually-hidden">${isTeam?'우리 팀 소식':'소식'}</h1><div class="news-controls">${filters}<div class="desktop-screen-actions">${screenActionMarkup()}</div></div><div class="news-layout"><div class="news-feed">${data.map(postCard).join('')||'<div class="empty">아직 소식이 없습니다.</div>'}</div><aside class="news-side"><h2>${isTeam?'후원 친구':'내가 응원하는 곳'}</h2>${isTeam?`<p class="team-news-count"><strong>${team(state.workspaceTeamId).supporters}</strong>명</p><button class="btn wide" data-action="nav-friends">후원 친구 보기</button>`:teams.map(t=>friendRow(t,true)).join('')}</aside></div></div>`;
}
function renderTeamPage(own=false){const t=team(state.activeTeam);const items=posts.filter(p=>p.team===t.id&&(own||p.audience==='전체 공개'));document.querySelector('#main').innerHTML=`<div class="page profile-page team-profile ${own?'root-page':'detail-page'}">${own?'<h1 class="visually-hidden">팀 프로필</h1>':`<header class="detail-topline">${iconButton('back','back-profile','이전 화면')}<h1>참여팀</h1></header>`}<div class="profile-cover-wrap"><img class="team-cover" src="${t.image}" alt="${esc(t.name)}의 활동">${own?`<div class="desktop-screen-actions team-desktop-action">${screenActionMarkup()}</div>`:''}</div><section class="profile-summary">${avatar(t,'big')}<div class="profile-summary-content"><h2 class="profile-name" style="font-size:24px">${esc(t.name)}${verify()}</h2><p class="profile-bio">${esc(t.bio)}</p><div class="profile-stats"><span><strong>${t.supporters}</strong>후원 친구</span><span>${esc(t.category)}</span></div></div><div class="profile-actions">${own?`<button class="btn light" data-action="compose-post">${icon('plus')}소식 올리기</button>`:`<button class="btn" data-action="friend-chat" data-id="${t.id}">${icon('chat')}대화</button><button class="btn primary" data-action="donate" data-id="${t.id}">후원하기</button>`}</div></section><div class="profile-filter"><div class="tab-line"><button class="active">활동 소식</button></div><span>${items.length}개의 이야기</span></div>${photoGrid(items)}</div>`}
function renderSubmissions(){const list=allowedSubmissions().filter(s=>state.adminFilter==='all'||s.status===state.adminFilter);document.querySelector('#main').innerHTML=`<div class="page submissions-page root-page"><h1 class="visually-hidden">접수 자료</h1><div class="submission-controls"><div class="chips">${['all','접수됨','검토 중','보완 요청','완료'].map(s=>`<button class="chip ${state.adminFilter===s?'active':''}" data-adminfilter="${s}">${s==='all'?'전체':s}</button>`).join('')}</div><div class="desktop-screen-actions">${screenActionMarkup()}</div></div><div class="submission-grid">${list.map(s=>`<button class="submission" data-action="submission" data-id="${s.id}">${statusPill(s.status)}<h2>${esc(s.title)}</h2><p>${esc(team(s.team).name)} · 담당 ${esc(s.assignee)}</p><div class="foot"><span>첨부 ${s.files.length}개 · 최근 접수 ${s.time}</span>${icon('chevron')}</div></button>`).join('')||'<div class="empty">이 상태의 접수 건이 없습니다.</div>'}</div></div>`}

// Screen interactions are held in memory for this prototype. No real messages or payments are sent.
let toastTimer;
const modal=document.querySelector('#modal');
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3000);}
function openModal(content,classes=''){modal.className='modal '+classes;document.querySelector('#modal-content').innerHTML=content;if(!modal.open)modal.showModal();}
function closeModal(){if(modal.open)modal.close();}
function modalHeader(title){return `<header class="modal-head"><h2>${esc(title)}</h2>${iconButton('close','close-modal','닫기')}</header>`}
function setRole(role){
 const key=role==='supporter'?'personal':role==='admin'?'operations':access.memberships[0]?'team:'+access.memberships[0].teamId:null;
 if(!key||!switchWorkspace(key))throw new Error('이 공간을 이용할 권한이 없습니다.');
}

function navigate(view){
 if(!allowedView(view)){toast('이 메뉴를 이용할 권한이 없습니다.');return;}
 preserveDraft();closeWorkspaceMenu();closeModal();state.view=view;state.mobileOpen=false;state.profilePerson=null;state.friendQuery='';render();
}

function openRoom(id){
 const r=roomList().find(r=>r.id===id);if(!access.signedIn||!r)return;
 preserveDraft();state.room=id;state.view=state.role==='admin'?'inbox':'chats';state.mobileOpen=true;
 access.unread[access.space]=0;closeModal();render();
}

function addMessage(text){
 if(!text.trim()||!access.signedIn||!roomList().some(r=>r.id===state.room)||state.role==='team'&&!teamCan('chat'))return false;
 const id=state.room;messages[id]??=[];messages[id].push({from:state.role,teamId:state.workspaceTeamId,actor:me.name,text:text.trim(),time:'방금'});
 state.workspaceDrafts[access.space+':'+id]='';renderChat();return true;
}

function friendChat(id){
 const t=teams.find(t=>t.id===id);
 if(t){if(state.role!=='supporter')switchWorkspace('personal');openRoom(t.id+'-chat');return;}
 if(state.role==='team'&&!teamCan('chat'))return;
 const p=newChatContacts().find(p=>p.id===id)||people.find(p=>p.id===id)||(state.role==='team'&&teamCan('donors')?teamDonors():[]).find(p=>p.id===id)||person(id);
 const roomid=(state.role==='team'?'team:'+state.workspaceTeamId+':':'personal:')+id+'-chat';
 const existing=roomList().find(r=>r.id===roomid||r.peer.id===id);if(existing){openRoom(existing.id);return;}
 state.groupRooms.push({id:roomid,title:p.name,peer:p,kind:'person',time:'방금',preview:'새로운 대화를 시작해 보세요.',role:state.role,teamId:state.workspaceTeamId});messages[roomid]=[];openRoom(roomid);
}

function showPost(id){const p=posts.find(p=>p.id===id);if(!p)return;const a=p.mine?me:p.person?person(p.person):team(p.team);const comments=state.comments[id]||[];openModal(`<div class="modal-head"><div class="chat-identity">${avatar(a,'sm')}<div><h3>${esc(a.name)}${p.team?verify():''}</h3><span class="detail-meta">${esc(p.date)} · ${esc(p.audience)}</span></div></div>${iconButton('close','close-modal','소식 닫기')}</div><img class="modal-image" src="${p.image}" alt="${esc(p.title)}"><div class="modal-body"><h2>${esc(p.title)}</h2><p>${esc(p.text)}</p><div class="detail-buttons"><button class="btn ${p.liked?'light':''}" data-action="like-detail" data-id="${id}" aria-pressed="${p.liked}">${icon('heart')}응원 ${p.likes}</button>${p.team?`<button class="btn" data-action="team-page" data-id="${p.team}">팀 페이지 ${icon('chevron')}</button>`:''}</div><div class="info-separator"><h3 style="font-size:14px;margin-bottom:13px">댓글 ${comments.length}</h3>${comments.map(c=>`<div style="padding:8px 0;font-size:13px"><strong>${esc(c.name)}</strong> <span class="muted">${esc(c.text)}</span></div>`).join('')}<form id="comment-form" data-id="${id}" style="display:flex;gap:8px;margin-top:12px"><label class="field" style="margin:0;flex:1"><input name="comment" maxlength="300" required placeholder="따뜻한 말을 남겨주세요" aria-label="댓글 입력"></label><button class="btn light" type="submit">등록</button></form></div></div>`,'post-detail');}
function showFile(id){const f=sampleFiles[id]||state.localFiles.get(id);if(!f)return;openModal(`${modalHeader('파일 보기')}<div class="modal-body"><div class="actions" style="margin-bottom:20px"><span class="file-icon ${f.type==='PDF'?'':'word'}">${esc(f.type)}</span><div class="file-copy"><strong>${esc(f.name)}</strong><span>${esc(f.size)}${f.url?'':' · 예시 문서'}</span></div></div>${f.image?`<img src="${f.url}" alt="${esc(f.name)}" style="width:100%;border-radius:12px">`:f.url&&f.type==='PDF'?`<iframe title="${esc(f.name)} 미리보기" src="${f.url}" style="width:100%;height:420px;border:1px solid #eee;border-radius:12px"></iframe>`:f.url?'<div class="doc-preview"><p>첨부한 문서는 원본 파일로 열어 확인할 수 있습니다.</p></div>':`<div class="doc-preview"><h3>${esc(f.title)}</h3>${f.lines.map(l=>`<p>${esc(l)}</p>`).join('')}</div>`}${f.url?`<a class="btn wide" style="margin-top:18px" href="${f.url}" download="${esc(f.name)}">${icon('download')}원본 파일 열기</a>`:'<p class="modal-note">화면 구성을 확인하기 위한 예시 문서입니다.</p>'}</div>`);}
function showSubmission(id){if(!canReadSubmission(id)){toast('이 접수 자료에 접근할 권한이 없습니다.');return;}const s=submissions.find(s=>s.id===id);if(!s)return;openModal(`${modalHeader('접수 내용')}<div class="modal-body">${statusPill(s.status)}<h2 style="margin:15px 0 7px">${esc(s.title)}</h2><p class="intro">${esc(team(s.team).name)} · 담당 ${esc(s.assignee)}</p><div class="detail-row"><span>최근 접수</span><span>${esc(s.time)}</span></div><div class="detail-row"><span>자료 버전</span><span>${s.files.length}개 파일 보관</span></div><h3 style="margin:25px 0 12px">제출 자료</h3>${s.files.map((f,i)=>`<div style="margin-bottom:10px">${i===0?'<span class="small orange" style="display:block;margin-bottom:6px">최신 제출본</span>':''}${fileCard(f)}</div>`).join('')}${state.role==='admin'?`<div class="info-separator"><h3 style="font-size:14px;margin-bottom:8px">내부 메모</h3><p class="small muted">${esc(s.note||'아직 작성한 메모가 없습니다.')}</p><button class="btn" data-action="internal-note" data-id="${id}" style="margin-top:13px">메모 작성</button></div>`:''}</div><div class="modal-foot">${state.role==='admin'?`<button class="btn" data-action="review" data-id="${id}" data-status="보완 요청">보완 요청</button><button class="btn primary" data-action="review" data-id="${id}" data-status="${s.status==='접수됨'?'검토 중':'완료'}">${s.status==='접수됨'?'검토 시작':'완료 처리'}</button>`:`<button class="btn" data-action="room" data-id="${s.room}">대화에서 보기</button><button class="btn primary" data-action="attach">자료 추가</button>`}</div>`);}
function composePost(){state.postImage=state.role==='team'?team(state.workspaceTeamId).image:images.river;state.postImages=[];openModal(`${modalHeader(state.role==='team'?'팀 소식 올리기':'나의 활동 올리기')}<form id="post-form"><div class="modal-body"><div class="chat-identity" style="margin-bottom:20px">${avatar(currentIdentity(),'sm')}<div><h3>${esc(currentIdentity().name)}</h3><p class="small muted">${state.role==='team'?'후원자에게 전할 오늘의 이야기':'나의 일상과 활동을 기록해 보세요'}</p></div></div><div id="image-choices" class="image-choices">${Object.values(images).map(src=>`<button type="button" class="image-choice ${state.postImage===src?'active':''}" data-action="choose-image" data-src="${src}" aria-label="활동 사진 선택"><img src="${src}" alt="활동 사진"></button>`).join('')}</div><button type="button" class="btn wide" data-action="upload-post-image" style="margin-top:10px">${icon('image')}내 사진 선택</button><label class="field"><span>제목</span><input name="title" placeholder="오늘의 이야기에 이름을 붙여주세요" maxlength="80" required></label><label class="field"><span>내용</span><textarea name="body" placeholder="함께 나누고 싶은 소식을 적어주세요" required maxlength="2000"></textarea></label><label class="field"><span>공개 범위</span><select name="audience">${state.role==='team'?'<option>전체 공개</option><option>후원자 공개</option>':'<option>친구 공개</option><option>전체 공개</option><option>나만 보기</option>'}</select></label>${state.role==='team'?'<p class="modal-note">전체 공개 소식은 자동 반영을 켠 후원자의 프로필에도 표시됩니다.</p>':''}</div><div class="modal-foot"><button type="button" class="btn" data-action="close-modal">취소</button><button class="btn primary" type="submit">${state.role==='team'?'소식 게시':'활동 게시'}</button></div></form>`);}
function newChat(){openModal(`${modalHeader('새 대화')}<div class="modal-body"><div class="attachment-options"><button class="attachment-option" data-action="pick-one-friend">${icon('chat')}<strong>개인 대화</strong><span>친구와 나누는 이야기</span></button><button class="attachment-option" data-action="new-group">${icon('friends')}<strong>단체 대화</strong><span>함께할 친구 초대</span></button></div></div>`);}
function newGroup(){const list=state.role==='team'?newChatContacts():people;openModal(`${modalHeader('단체 대화방 만들기')}<form id="group-form"><div class="modal-body"><label class="field"><span>대화방 이름</span><input name="title" maxlength="40" required placeholder="예: 토요일, 함께 걷기"></label><p class="intro">함께 대화할 친구를 선택해 주세요. 상대가 초대를 수락하면 함께할 수 있어요.</p>${list.map(p=>`<label class="select-person">${avatar(p,'sm')}<span><strong>${esc(p.name)}</strong><p>${esc(p.bio)}</p></span><input type="checkbox" name="members" value="${p.id}" aria-label="${esc(p.name)} 선택"></label>`).join('')}</div><div class="modal-foot"><button type="button" class="btn" data-action="close-modal">취소</button><button type="submit" class="btn primary">대화방 만들기</button></div></form>`);}
function roomInfo(){const r=activeRoom(),s=submissions.find(s=>s.room===r.id);if(s){showSubmission(s.id);return;}openModal(`${modalHeader('대화방 정보')}<div class="modal-body"><div class="info-profile">${avatar(r.peer,'big')}<h2>${esc(r.title)}</h2><p>${r.kind==='group'?`${r.count||1}명 참여${r.pending?' · '+r.pending+'명 초대 대기':''}`:r.kind==='team'?'후원으로 연결된 친구':'서로 친구로 연결되어 있어요'}</p></div><button class="switch-row" style="width:100%;text-align:left" data-action="toggle-mute"><span>대화 알림<p>${state.muted.has(r.id)?'알림을 받지 않고 있어요':'새 메시지를 알려드려요'}</p></span><span>${state.muted.has(r.id)?'꺼짐':'켜짐'} ${icon('bell')}</span></button>${r.kind==='group'?'<p class="modal-note">초대를 수락한 구성원만 새 대화를 볼 수 있습니다.</p>':r.kind==='team'?`<button class="btn wide" data-action="team-page" data-id="${r.peer.id}" style="margin-top:20px">참여팀 페이지 ${icon('chevron')}</button>`:''}</div>`);}
function editProfile(){state.pendingAvatar=null;const p=currentIdentity();openModal(`${modalHeader(state.role==='team'?'팀 프로필 편집':'프로필 편집')}<form id="profile-form"><div class="modal-body"><div id="avatar-preview" style="display:flex;justify-content:center;padding:10px 0">${avatar(p,'large')}</div><button type="button" class="btn wide" data-action="change-avatar">프로필 사진 변경</button><label class="field"><span>${state.role==='team'?'팀 이름':'이름'}</span><input name="name" value="${esc(p.name)}" required maxlength="24"></label><label class="field"><span>소개</span><textarea name="bio" maxlength="120">${esc(p.bio||'')}</textarea></label>${state.role==='supporter'?`<label class="field"><span>프로필 공개 범위</span><select name="privacy">${['친구 공개','전체 공개','나만 보기'].map(s=>`<option ${state.privacy===s?'selected':''}>${s}</option>`).join('')}</select></label>`:''}</div><div class="modal-foot"><button type="button" class="btn" data-action="close-modal">취소</button><button type="submit" class="btn primary">저장</button></div></form>`);}
function profileSettings(){openModal(`${modalHeader('프로필 표시 관리')}<form id="settings-form"><div class="modal-body"><label class="field"><span>프로필 공개 범위</span><select name="privacy">${['친구 공개','전체 공개','나만 보기'].map(s=>`<option ${s===state.privacy?'selected':''}>${s}</option>`).join('')}</select></label><p class="intro">내 프로필에 표시할 후원팀과 소식 자동 반영 여부를 선택하세요.</p>${teams.map(t=>`<div style="margin:25px 0"><div class="chat-identity">${avatar(t,'sm')}<h3 style="font-size:14px">${esc(t.name)}</h3></div><label class="switch-row"><span>후원팀을 프로필에 표시</span><input type="checkbox" name="show-${t.id}" ${state.showTeam[t.id]?'checked':''}></label><label class="switch-row"><span>새 소식 자동 반영<p>공개 활동 소식을 내 기록에 함께 표시</p></span><input type="checkbox" name="auto-${t.id}" ${state.auto[t.id]?'checked':''}></label></div>`).join('')}</div><div class="modal-foot"><button class="btn" type="button" data-action="close-modal">취소</button><button class="btn primary" type="submit">저장</button></div></form>`);}
function reviewDialog(id,status){const s=submissions.find(s=>s.id===id);if(!s||!inOperations()||!canReadSubmission(id))return;openModal(`${modalHeader(status==='완료'?'완료 처리':status==='검토 중'?'검토 시작':'보완 요청')}<form id="review-form" data-id="${id}" data-status="${status}"><div class="modal-body"><p class="intro">${esc(team(s.team).name)} · ${esc(s.title)}</p><label class="field"><span>참여팀에 전할 내용</span><textarea name="message" required maxlength="1000">${status==='완료'?'보내주신 자료 확인을 마쳤습니다. 감사합니다.':status==='검토 중'?'자료를 확인하고 검토를 시작했습니다.':'아래 내용을 보완해 보내주세요.\n'}</textarea></label><p class="modal-note">이 내용은 참여팀과의 운영 대화에 표시됩니다.</p></div><div class="modal-foot"><button class="btn" type="button" data-action="close-modal">취소</button><button class="btn primary" type="submit">${status==='완료'?'완료 처리':status==='검토 중'?'검토 시작':'요청 보내기'}</button></div></form>`);}
function attach(){openModal(`${modalHeader('사진 · 파일 보내기')}<div class="modal-body"><div class="attachment-options"><button class="attachment-option" data-action="pick-image">${icon('image')}<strong>사진</strong><span>활동 사진을 함께 보내세요</span></button><button class="attachment-option" data-action="pick-file">${icon('file')}<strong>파일</strong><span>PDF · 워드 문서</span></button></div><p class="modal-note">파일당 최대 50MB, 한 번에 10개까지 선택할 수 있습니다.</p></div>`);}
function showPerson(id){const p=people.find(p=>p.id===id)||donors.find(p=>p.id===id)||person(id);if(state.role==='supporter'&&people.some(p=>p.id===id)){state.profilePerson=id;state.view='profile';closeModal();render();return;}openModal(`${modalHeader('친구 프로필')}<div class="modal-body"><div class="info-profile">${avatar(p,'large')}<h2>${esc(p.name)}</h2><p>${esc(p.bio||'함께해 주셔서 감사합니다.')}</p></div><button class="btn wide light" style="margin-top:20px" data-action="friend-chat" data-id="${p.id}">${icon('chat')}대화하기</button></div>`);}
function sharePost(id){openModal(`${modalHeader('대화로 보내기')}<div class="modal-body"><p class="intro">소식을 나누고 싶은 대화방을 선택하세요.</p>${roomList().filter(r=>r.kind!=='ops').map(r=>`<button class="select-person" style="width:100%" data-action="share-to-room" data-id="${id}" data-room="${r.id}">${avatar(r.peer,'sm')}<strong>${esc(r.title)}</strong>${icon('chevron')}</button>`).join('')}</div>`);}

document.addEventListener('click',e=>{
 const roleButton=e.target.closest('[data-role]');if(roleButton){setRole(roleButton.dataset.role);return;}
 const view=e.target.closest('[data-view]');if(view){navigate(view.dataset.view);return;}
 const c=e.target.closest('[data-chatfilter]');if(c){state.chatFilter=c.dataset.chatfilter;renderChat();return;}
 const pf=e.target.closest('[data-profilefilter]');if(pf){state.profileFilter=pf.dataset.profilefilter;renderProfile();return;}
 const nf=e.target.closest('[data-newsfilter]');if(nf){state.newsFilter=nf.dataset.newsfilter;renderNews();return;}
 const af=e.target.closest('[data-adminfilter]');if(af){state.adminFilter=af.dataset.adminfilter;renderSubmissions();return;}
 const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action,id=b.dataset.id;
 switch(action){
 case 'home':navigate(state.role==='admin'?'inbox':'chats');break;
 case 'close-modal':closeModal();break;
 case 'room':openRoom(id);break;
 case 'back-list':state.mobileOpen=false;renderChat();break;
 case 'nav-chats':navigate('chats');break;
 case 'nav-friends':navigate('friends');break;
 case 'focus-search':document.querySelector('#chat-search')?.focus();break;
 case 'new-chat':newChat();break;
 case 'new-group':newGroup();break;
 case 'pick-one-friend':openModal(`${modalHeader('개인 대화')}<div class="modal-body">${newChatContacts().map(p=>`<button class="select-person" style="width:100%" data-action="friend-chat" data-id="${p.id}">${avatar(p,'sm')}<strong>${esc(p.name)}</strong></button>`).join('')}</div>`);break;
 case 'friend-chat':friendChat(id);break;
 case 'person':showPerson(id);break;
 case 'post':showPost(id);break;
 case 'file':showFile(id);break;
 case 'submission':showSubmission(id);break;
 case 'review':reviewDialog(id,b.dataset.status);break;
 case 'internal-note':{const s=submissions.find(s=>s.id===id);if(state.role!=='admin')break;openModal(`${modalHeader('내부 메모')}<form id="note-form" data-id="${id}"><div class="modal-body"><p class="intro">운영 담당자에게만 표시되는 메모입니다.</p><label class="field"><span>메모</span><textarea name="note" maxlength="1500">${esc(s.note)}</textarea></label></div><div class="modal-foot"><button class="btn primary" type="submit">저장</button></div></form>`);break;}
 case 'attach':attach();break;
 case 'pick-image':case 'pick-file':{const input=document.querySelector('#chat-file');input.accept=action==='pick-image'?'image/*':'.pdf,.doc,.docx';input.value='';closeModal();input.click();break;}
 case 'compose-post':composePost();break;
 case 'choose-image':state.postImage=b.dataset.src;document.querySelectorAll('.image-choice').forEach(x=>x.classList.toggle('active',x===b));break;
 case 'upload-post-image':document.querySelector('#post-file').value='';document.querySelector('#post-file').click();break;
 case 'edit-profile':editProfile();break;
 case 'change-avatar':document.querySelector('#avatar-file').value='';document.querySelector('#avatar-file').click();break;
 case 'profile-settings':profileSettings();break;
 case 'own-profile':state.profilePerson=null;renderProfile();break;
 case 'team-page':state.activeTeam=id;state.view='team';closeModal();render();break;
 case 'back-profile':state.view=state.role==='team'?'profile':'profile';state.profilePerson=null;render();break;
 case 'like':case 'like-detail':{const p=posts.find(p=>p.id===id);p.likes+=p.liked?-1:1;p.liked=!p.liked;if(action==='like-detail')showPost(id);else renderNews();break;}
 case 'post-menu':openModal(`${modalHeader('소식 관리')}<div class="modal-body"><button class="btn wide" data-action="share-post" data-id="${id}">${icon('send')}대화로 보내기</button>${state.role==='supporter'?`<button class="btn wide" style="margin-top:10px" data-action="hide-post" data-id="${id}">내 프로필에서 숨기기</button>`:''}${state.role==='team'&&posts.find(p=>p.id===id)?.team===state.workspaceTeamId?`<button class="btn wide" style="margin-top:10px" data-action="unpublish" data-id="${id}">소식 비공개로 변경</button>`:''}</div>`);break;
 case 'hide-post':state.hiddenPosts.add(id);closeModal();render();toast('내 프로필에서 이 소식을 숨겼습니다.');break;
 case 'unpublish':{const p=posts.find(p=>p.id===id);if(p&&state.role==='team'&&teamCan('publish')&&p.team===state.workspaceTeamId){p.audience='후원자 공개';closeModal();render();toast('후원자 공개로 변경했습니다. 개인 프로필에서는 숨겨집니다.');}break;}
 case 'share-post':sharePost(id);break;
 case 'share-to-room':messages[b.dataset.room]??=[];messages[b.dataset.room].push({from:state.role,post:id,time:'방금'});closeModal();openRoom(b.dataset.room);toast('선택한 대화에 소식을 추가했습니다.');break;
 case 'room-info':case 'group-info':roomInfo();break;
 case 'toggle-mute':state.muted.has(state.room)?state.muted.delete(state.room):state.muted.add(state.room);closeModal();renderChat();toast(state.muted.has(state.room)?'이 대화의 알림을 껐습니다.':'이 대화의 알림을 켰습니다.');break;
 case 'room-search':openModal(`${modalHeader('대화 내용 검색')}<div class="modal-body"><label class="field"><span>검색어</span><input id="message-search" placeholder="대화에서 찾고 싶은 단어" autofocus></label><div id="message-search-results" class="small muted">검색어를 입력하세요.</div></div>`);break;
 case 'accept-friend':{const ix=requests.findIndex(p=>p.id===id);if(ix>=0){const p=requests.splice(ix,1)[0];people.push({...p,bio:'새롭게 연결된 친구예요.'});renderFriends();toast(`${p.name}님과 친구가 되었습니다.`);}break;}
 case 'reject-friend':{const ix=requests.findIndex(p=>p.id===id);if(ix>=0)requests.splice(ix,1);renderFriends();toast('친구 요청을 목록에서 숨겼습니다.');break;}
 case 'add-friend':openModal(`${modalHeader('친구 추가')}<form id="add-friend-form"><div class="modal-body"><p class="intro">친구 이름을 찾아 요청을 보내세요.</p><label class="field"><span>이름</span><input name="name" required maxlength="24" placeholder="예: 김다은"></label><p class="modal-note">이 화면에서는 예시 친구에게 요청하는 흐름을 확인할 수 있습니다.</p></div><div class="modal-foot"><button type="submit" class="btn primary">친구 찾기</button></div></form>`);break;
 case 'send-friend-request':state.friendSent.add(id);b.textContent='요청 보냄';b.disabled=true;toast('친구 요청 상태를 확인할 수 있습니다.');break;
 case 'more-friends':state.friendLimit+=20;document.querySelector('#friend-results').innerHTML=friendResults();if(state.friendLimit>=teamDonors().length)b.hidden=true;break;
 case 'broadcast':openModal(`${modalHeader('후원 친구에게 전체 공지')}<form id="broadcast-form"><div class="modal-body"><div class="connection-note" style="margin:0 0 15px">${icon('friends')}${team(state.workspaceTeamId).supporters}명의 후원 친구에게 각각 전달됩니다.</div><label class="field"><span>공지 내용</span><textarea name="text" placeholder="후원자에게 전할 소식을 입력하세요" required maxlength="1000"></textarea></label><p class="modal-note">수신자는 서로의 명단을 볼 수 없고, 답장은 우리 팀과의 개인 대화로 이어집니다.</p></div><div class="modal-foot"><button type="button" class="btn" data-action="close-modal">취소</button><button type="submit" class="btn primary">전달 내용 확인</button></div></form>`);break;
 case 'donate':openModal(`${modalHeader('따뜻한 마음을 더해주세요')}<div class="modal-body"><div class="chat-identity">${avatar(team(id),'sm')}<h3>${esc(team(id).name)}</h3></div><div class="donation-amounts">${['1,000원','5,000원','10,000원'].map(x=>`<button class="btn" data-action="donation-amount">${x}</button>`).join('')}</div><p class="intro">작은 마음이 모여 꾸준한 활동을 이어갑니다.</p><p class="modal-note">후원 화면 미리보기입니다. 실제 결제는 진행되지 않습니다.</p></div><div class="modal-foot"><button class="btn primary" data-action="close-modal">확인</button></div>`);break;
 case 'donation-amount':document.querySelectorAll('.donation-amounts .btn').forEach(x=>x.classList.toggle('light',x===b));break;
 case 'operator-info':openModal(`${modalHeader('운영 담당자')}<div class="modal-body"><div class="chat-identity">${avatar(currentIdentity(),'big')}<div><h2>김하늘</h2><p class="muted small">모두의기부 · 운영 담당</p></div></div><p class="modal-note">배정된 팀의 운영 대화와 접수 자료를 확인하는 화면입니다.</p></div>`);break;
 }
});
document.addEventListener('input',e=>{
 if(e.target.id==='chat-search'){const term=e.target.value.trim();let list=roomList().filter(r=>(r.title+' '+r.preview).includes(term));document.querySelector('#room-results').innerHTML=list.map(roomRow).join('')||'<div class="empty">검색 결과가 없습니다.</div>';}
 if(e.target.id==='friend-search'){state.friendQuery=e.target.value.trim();document.querySelector('#friend-results').innerHTML=friendResults();document.querySelectorAll('#team-friends .team-friend').forEach(row=>row.hidden=!row.dataset.search.includes(state.friendQuery));}
 if(e.target.id==='message-input'){e.target.style.height='44px';e.target.style.height=Math.min(120,e.target.scrollHeight)+'px';}
 if(e.target.id==='message-search'){const q=e.target.value.trim(),data=(messages[state.room]||[]).filter(m=>q&&(m.text||'').includes(q));document.querySelector('#message-search-results').innerHTML=data.length?data.map(m=>`<div style="padding:14px 0;border-bottom:1px solid #eee"><p>${esc(m.text)}</p><span class="small muted">${esc(m.time)}</span></div>`).join(''):q?'일치하는 대화가 없습니다.':'검색어를 입력하세요.';}
});
document.addEventListener('keydown',e=>{if(e.target.id==='message-input'&&e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();document.querySelector('#chat-form').requestSubmit();}});
document.addEventListener('submit',e=>{
 const f=e.target;e.preventDefault();const data=new FormData(f);
 if(f.id==='chat-form'){const input=document.querySelector('#message-input');if(addMessage(input.value)){document.querySelector('#message-input')?.focus();}return;}
 if(f.id==='group-form'){const members=data.getAll('members');if(!members.length){toast('초대할 친구를 한 명 이상 선택해 주세요.');return;}const id='group-'+Date.now();state.groupRooms.push({id,title:String(data.get('title')).trim(),peer:{name:String(data.get('title')),short:'모임',color:'blue'},kind:'group',role:state.role,teamId:state.workspaceTeamId,time:'방금',preview:'새로운 단체 대화방',count:1,pending:members.length});messages[id]=[{system:members.length+'명의 초대 수락을 기다리고 있습니다.'}];openRoom(id);toast('단체 대화방을 만들었습니다.');return;}
 if(f.id==='profile-form'){const p=currentIdentity();p.name=String(data.get('name')).trim();p.short=p.name.slice(-2);p.bio=String(data.get('bio')).trim();if(state.pendingAvatar)p.photo=state.pendingAvatar;if(data.has('privacy'))state.privacy=String(data.get('privacy'));closeModal();render();toast('프로필을 저장했습니다.');return;}
 if(f.id==='settings-form'){state.privacy=String(data.get('privacy'));for(const t of teams){state.showTeam[t.id]=data.has('show-'+t.id);state.auto[t.id]=data.has('auto-'+t.id);}closeModal();render();toast('프로필 표시 설정을 저장했습니다.');return;}
 if(f.id==='post-form'){const id='post-'+Date.now();posts.unshift({id,team:state.role==='team'?state.workspaceTeamId:undefined,mine:state.role!=='team',image:state.postImage,title:String(data.get('title')).trim(),text:String(data.get('body')).trim(),date:'방금',likes:0,liked:false,audience:String(data.get('audience'))});closeModal();state.view=state.role==='team'?'news':'profile';state.profileFilter='all';render();toast(state.role==='team'&&data.get('audience')==='전체 공개'?'공개 소식을 게시했습니다. 후원자 프로필에도 반영됩니다.':'활동을 게시했습니다.');return;}
 if(f.id==='comment-form'){const text=String(data.get('comment')).trim();if(!text)return;const id=f.dataset.id;state.comments[id]??=[];state.comments[id].push({name:currentIdentity().name,text});showPost(id);return;}
 if(f.id==='review-form'){const s=submissions.find(s=>s.id===f.dataset.id);if(state.role!=='admin'||!s)return;s.status=f.dataset.status;messages[s.room]??=[];messages[s.room].push({from:'admin',text:String(data.get('message')).trim(),time:'방금'},{from:'admin',receipt:s.id,time:'방금'});closeModal();render();toast('접수 상태와 대화 내용을 업데이트했습니다.');return;}
 if(f.id==='note-form'){const s=submissions.find(s=>s.id===f.dataset.id);if(state.role!=='admin'||!s)return;s.note=String(data.get('note')).trim();showSubmission(s.id);toast('내부 메모를 저장했습니다.');return;}
 if(f.id==='add-friend-form'){const name=String(data.get('name')).trim();openModal(`${modalHeader('친구 찾기')}<div class="modal-body"><div class="select-person">${avatar({name,short:name.slice(-2),color:'blue'})}<div><strong>${esc(name)}</strong><p>친구 요청 후 수락하면 연결됩니다.</p></div></div><button class="btn primary wide" style="margin-top:20px" data-action="send-friend-request" data-id="${esc(name)}" ${state.friendSent.has(name)?'disabled':''}>${state.friendSent.has(name)?'요청 보냄':'친구 요청'}</button><p class="modal-note">예시 검색 결과입니다. 실제 계정에는 요청이 전송되지 않습니다.</p></div>`);return;}
 if(f.id==='broadcast-form'){openModal(`${modalHeader('전체 공지 미리보기')}<div class="modal-body"><span class="status-pill pending">받는 사람 · 후원 친구 ${team(state.workspaceTeamId).supporters}명</span><div class="doc-preview" style="margin-top:20px;min-height:160px"><p style="white-space:pre-wrap">${esc(data.get('text'))}</p></div><p class="modal-note">전달 화면을 확인하는 시안입니다. 실제 메시지는 발송되지 않습니다.</p></div><div class="modal-foot"><button class="btn primary" data-action="close-modal">확인</button></div>`);}
});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
document.querySelector('#chat-file').addEventListener('change',e=>{
 const files=Array.from(e.target.files||[]);if(files.length>10){toast('한 번에 10개까지 선택해 주세요.');return;}
 const accepted=files.filter(f=>f.size<=50*1024*1024&&(f.type.startsWith('image/')||/\.(pdf|docx?)$/i.test(f.name)));
 if(accepted.length!==files.length)toast('형식 또는 50MB 한도를 확인해 주세요.');
 messages[state.room]??=[];
 for(const file of accepted){const id='local-'+Date.now()+'-'+Math.random().toString(36).slice(2);const image=file.type.startsWith('image/');state.localFiles.set(id,{name:file.name,type:image?'사진':file.name.split('.').pop().toUpperCase(),size:(file.size/1048576).toFixed(1)+' MB',url:URL.createObjectURL(file),image});messages[state.room].push({from:state.role,file:id,time:'방금'});const sub=submissions.find(s=>s.room===state.room);if(sub&&state.role==='team'){sub.files.unshift(id);sub.status='접수됨';sub.time='방금';}}
 if(accepted.length){const sub=submissions.find(s=>s.room===state.room);if(sub&&state.role==='team')messages[state.room].push({from:'admin',receipt:sub.id,time:'방금'});renderChat();toast('선택한 파일을 대화 화면에 추가했습니다.');}
});
document.querySelector('#post-file').addEventListener('change',e=>{const f=e.target.files?.[0];if(!f)return;if(!f.type.startsWith('image/')||f.size>50*1024*1024){toast('50MB 이하의 사진을 선택해 주세요.');return;}state.postImage=URL.createObjectURL(f);state.postImages=[state.postImage];document.querySelector('#image-choices').innerHTML=`<button type="button" class="image-choice active" style="grid-column:1/-1;aspect-ratio:2" aria-label="선택한 사진"><img src="${state.postImage}" alt="새 활동에 사용할 사진"></button>`;});
document.querySelector('#avatar-file').addEventListener('change',e=>{const f=e.target.files?.[0];if(!f)return;if(!f.type.startsWith('image/')||f.size>50*1024*1024){toast('50MB 이하의 사진을 선택해 주세요.');return;}state.pendingAvatar=URL.createObjectURL(f);document.querySelector('#avatar-preview').innerHTML=avatar({...currentIdentity(),photo:state.pendingAvatar},'large');});
function registerAppTools(){
 const context=document.modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();
 const registrations=[{name:'get_communication_screen',title:'현재 모두아 화면',description:'미리보기의 현재 공간과 이용 가능한 공간을 읽습니다.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(){return {signedIn:access.signedIn,space:access.space,screen:state.view,availableSpaces:access.signedIn?availableSpaces().map(s=>({key:s.key,name:s.name})):[],prototype:true};}},
 {name:'navigate_communication_screen',title:'모두아 화면 열기',description:'로그인된 예시 계정에게 허용된 공간과 화면으로 이동합니다. 권한을 부여하거나 메시지를 보내지 않습니다.',inputSchema:{type:'object',properties:{space:{type:'string'},screen:{type:'string',enum:['friends','chats','news','profile','inbox','submissions','team-manage','ops-teams','ops-access']}},required:['space','screen'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!access.signedIn||!spaceExists(input.space))throw new Error('Access denied');switchWorkspace(input.space);if(!allowedView(input.screen))throw new Error('Screen not allowed');navigate(input.screen);return {space:access.space,screen:state.view,prototype:true};}}];
 for(const t of registrations){try{Promise.resolve(context.registerTool(t,{signal:lifecycle.signal})).catch(()=>{});}catch{}}
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
